// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint56 _changeFee, uint128 _virtualBase, uint128 _virtualNft, uint16 _feeRate) public {
        vm.assume(_changeFee != 1);
        c.initialize(address(0), address(0), _virtualBase, _virtualNft, _changeFee, _feeRate, bytes32(0), false, false);
        assertTrue(uint256(c.changeFee()) == uint256(_changeFee));
    }
}
